			confidence = models.FortinetRoughVersionMatch
		case cvemodels.FortinetVendorProductMatch:
			confidence = models.FortinetVendorProductMatch
		}
		if max.Score < confidence.Score {
			max = confidence
		}
	}
	return max
}

